begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select has_table('public','pdf_imports','Durable PDF imports exist');
select has_function('public','begin_pdf_import',array['uuid','text','integer','text']);
select has_function('public','confirm_pdf_import',array['uuid','text','integer']);
select ok((select not public and file_size_limit=10485760 and allowed_mime_types=array['application/pdf'] from storage.buckets where id='learning-pdfs'),'PDF bucket private and bounded');
insert into auth.users(id,email) values ('17000000-0000-4000-8000-000000000001','pdf-owner@paceon.example'),('17000000-0000-4000-8000-000000000002','pdf-foreign@paceon.example');
create temporary table claimed(v jsonb);
create temporary table fixture(v jsonb);
insert into fixture values ('{"pageCount":4,"title":"Sample","units":[{"title":"Front","startPage":1,"endPage":1},{"title":"Chapter","startPage":2,"endPage":4}],"textExcerpt":"sample","analysisOutline":"Sampled extracted text","warnings":[]}');
grant all on claimed,fixture to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub','17000000-0000-4000-8000-000000000001',true);
select is(begin_pdf_import('27000000-0000-4000-8000-000000000001','sample.pdf',100,repeat('a',64))->>'status','UPLOADING','Owner begins upload');
select is(begin_pdf_import('27000000-0000-4000-8000-000000000001','sample.pdf',100,repeat('a',64))->>'id','27000000-0000-4000-8000-000000000001','Identical retry reuses import');
select throws_ok($$select begin_pdf_import('27000000-0000-4000-8000-000000000001','other.pdf',100,repeat('a',64))$$,'40001',null,'Retry cannot replace file');
select throws_ok($$select begin_pdf_import(gen_random_uuid(),'../bad.pdf',100,repeat('a',64))$$,'23514',null,'Unsafe filename rejected');
select throws_ok($$select begin_pdf_import(gen_random_uuid(),'big.pdf',10485761,repeat('a',64))$$,'23514',null,'Oversize denied');
select throws_ok($$update pdf_imports set status='READY'$$,'42501',null,'Owner cannot forge status');
select throws_ok($$select claim_pdf_import()$$,'42501',null,'Owner cannot claim');
select throws_ok($$select finish_pdf_import(gen_random_uuid(),gen_random_uuid(),'{}',null)$$,'42501',null,'Owner cannot forge result');
select throws_ok($$select queue_pdf_import('27000000-0000-4000-8000-000000000001')$$,'PT409',null,'Queue requires stored object');
-- Storage metadata fixtures only, rolled back; real files must be removed through Storage API.
insert into storage.objects(bucket_id,name,owner_id,metadata) values ('learning-pdfs','17000000-0000-4000-8000-000000000001/27000000-0000-4000-8000-000000000001.pdf','17000000-0000-4000-8000-000000000001','{"size":100,"mimetype":"application/pdf"}');
select is(queue_pdf_import('27000000-0000-4000-8000-000000000001')->>'status','PENDING','Stored upload queued');
select is(queue_pdf_import('27000000-0000-4000-8000-000000000001')->>'status','PENDING','Queue idempotent');
with changed as (update storage.objects set metadata='{}' where bucket_id='learning-pdfs' returning id) select is((select count(*) from changed),0::bigint,'Storage objects immutable');
select set_config('request.jwt.claim.sub','17000000-0000-4000-8000-000000000002',true);
select is((select count(*) from pdf_imports),0::bigint,'Foreign imports hidden');
select is((select count(*) from storage.objects where bucket_id='learning-pdfs'),0::bigint,'Foreign files hidden');
select throws_ok($$select begin_pdf_import('27000000-0000-4000-8000-000000000001','sample.pdf',100,repeat('a',64))$$,'42501',null,'Foreign ID denied');
select throws_ok($$select confirm_pdf_import('27000000-0000-4000-8000-000000000001','Sample',0)$$,'42501',null,'Foreign confirmation denied');
select throws_ok($$select queue_pdf_import('27000000-0000-4000-8000-000000000001')$$,'42501',null,'Foreign queue denied');
select throws_ok($$select retry_pdf_import('27000000-0000-4000-8000-000000000001')$$,'42501',null,'Foreign retry denied');
select is(discard_pdf_import('27000000-0000-4000-8000-000000000001'),false,'Foreign discard cannot delete');
reset role;
set local role anon;
select throws_ok($$select count(*) from pdf_imports$$,'42501',null,'Anonymous cannot read imports');
select throws_ok($$select begin_pdf_import(gen_random_uuid(),'test.pdf',10,repeat('a',64))$$,'42501',null,'Anonymous cannot begin');
reset role;
set local role service_role;
insert into claimed select claim_pdf_import();
select is((select v->>'attempts' from claimed),'1','Claim counts attempt');
select is(claim_pdf_import(),null::jsonb,'Live lease not reclaimed');
select is(finish_pdf_import((select (v->>'id')::uuid from claimed),gen_random_uuid(),(select v from fixture),null),false,'Wrong lease denied');
select throws_ok($$select finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select v||'{"secret":"no"}' from fixture),null)$$,'23514',null,'Unknown result fields rejected');
select throws_ok($$select finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select jsonb_set(v,'{units,1,startPage}','3') from fixture),null)$$,'23514',null,'Coverage gap rejected');
select throws_ok($$select finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select jsonb_set(v,'{pageCount}','4.5') from fixture),null)$$,'23514',null,'Fractional pages rejected');
select throws_ok($$select finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select jsonb_set(v,'{warnings}','["SECRET"]') from fixture),null)$$,'23514',null,'Unknown warning rejected');
select ok(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select v from fixture),null),'Valid parsed result ready');
select is(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),null,'PARSE_ERROR'),false,'Completed lease cannot overwrite');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','17000000-0000-4000-8000-000000000001',true);
select throws_ok($$select confirm_pdf_import('27000000-0000-4000-8000-000000000001','Sample',5)$$,'23514',null,'Initial progress bounded');
select lives_ok($$select confirm_pdf_import('27000000-0000-4000-8000-000000000001','Chosen title',1)$$,'Owner confirms');
select is(confirm_pdf_import('27000000-0000-4000-8000-000000000001','Chosen title',1),(select resource_id from pdf_imports),'Confirm idempotent');
select throws_ok($$select confirm_pdf_import('27000000-0000-4000-8000-000000000001','Changed',1)$$,'PT409',null,'Different confirmation denied');
select ok((select type='BOOK' and workload_unit='PAGE' and source='PDF_IMPORT' and total_pages=4 and total_units=2 and initial_completed_workload=1 and status='ACTIVE' from resources where id=(select resource_id from pdf_imports)),'Book compatible with page planner');
select is((select count(*) from resource_units where resource_id=(select resource_id from pdf_imports)),2::bigint,'All units created once');
select ok((select bool_and(unit_type='SECTION' and parent_unit_id is null and workload=end_page-start_page+1) from resource_units where resource_id=(select resource_id from pdf_imports)),'Top level section workloads correct');
select is((select array_agg(start_page order by sequence) from resource_units where resource_id=(select resource_id from pdf_imports)),array[1,2],'Units ordered and contiguous');
select throws_ok($$select discard_pdf_import('27000000-0000-4000-8000-000000000001')$$,'PT409',null,'Imported cannot discard');
select throws_ok($$select retry_pdf_import('27000000-0000-4000-8000-000000000001')$$,'PT409',null,'Imported cannot retry');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('learning-pdfs','17000000-0000-4000-8000-000000000001/37000000-0000-4000-8000-000000000001.pdf','{"size":100}')$$,'42501',null,'Unreserved storage path denied');
select begin_pdf_import('27000000-0000-4000-8000-000000000008','retry.pdf',100,repeat('b',64));
insert into storage.objects(bucket_id,name,owner_id,metadata) values ('learning-pdfs','17000000-0000-4000-8000-000000000001/27000000-0000-4000-8000-000000000008.pdf','17000000-0000-4000-8000-000000000001','{"size":100,"mimetype":"application/pdf"}');
select queue_pdf_import('27000000-0000-4000-8000-000000000008');
reset role;
set local role service_role;
delete from claimed;
insert into claimed select claim_pdf_import();
update pdf_imports set lease_expires_at=clock_timestamp()-interval '1 second' where id='27000000-0000-4000-8000-000000000008';
select is(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select v from fixture),null),false,'Expired lease cannot finish');
select is(claim_pdf_import()->>'attempts','2','Expired lease retried');
select is(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),null,'PARSE_ERROR'),false,'Old worker loses CAS');
update pdf_imports set lease_expires_at=clock_timestamp()-interval '1 second' where id='27000000-0000-4000-8000-000000000008';
select is(claim_pdf_import()->>'attempts','3','Third attempt allowed');
update pdf_imports set lease_expires_at=clock_timestamp()-interval '1 second' where id='27000000-0000-4000-8000-000000000008';
select is(claim_pdf_import(),null::jsonb,'Exhaustion leaves no claim');
select is((select error_code from pdf_imports where id='27000000-0000-4000-8000-000000000008'),'WORKER_TIMEOUT','Exhaustion has safe timeout error');
reset role;
set local role authenticated;
select is(retry_pdf_import('27000000-0000-4000-8000-000000000008')->>'attempts','0','Owner parse retry resets attempts');
reset role;
set local role service_role;
delete from claimed;
insert into claimed select claim_pdf_import();
reset role;
set local role authenticated;
select throws_ok($$select discard_pdf_import('27000000-0000-4000-8000-000000000008')$$,'PT409',null,'Processing cannot discard');
reset role;
set local role service_role;
select throws_ok($$select finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),null,'raw text secret')$$,'23514',null,'Unsafe error denied');
select ok(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),'{"secret":"discard me"}','PARSE_ERROR'),'Worker can fail safely');
select ok((select result is null and lease_token is null and lease_expires_at is null from pdf_imports where id='27000000-0000-4000-8000-000000000008'),'Failure drops result and lease');
reset role;
set local role authenticated;
select retry_pdf_import('27000000-0000-4000-8000-000000000008');
reset role;
set local role service_role;
delete from claimed;
insert into claimed select claim_pdf_import();
select ok(finish_pdf_import((select (v->>'id')::uuid from claimed),(select (v->>'lease_token')::uuid from claimed),(select v from fixture),null),'Retried parse succeeds');
reset role;
set local role authenticated;
select lives_ok($$select confirm_pdf_import('27000000-0000-4000-8000-000000000008','Finished',4)$$,'Fully completed PDF confirms');
select is((select status::text from resources where id=(select resource_id from pdf_imports where id='27000000-0000-4000-8000-000000000008')),'COMPLETED','Full progress creates completed book');
update resources set title='Edited after import' where id=(select resource_id from pdf_imports where id='27000000-0000-4000-8000-000000000008');
select is(confirm_pdf_import('27000000-0000-4000-8000-000000000008','Finished',4),(select resource_id from pdf_imports where id='27000000-0000-4000-8000-000000000008'),'Confirmation retry survives resource edits');
select begin_pdf_import(('27000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'pending.pdf',100,repeat('a',64)) from generate_series(2,6) n;
select throws_ok($$select begin_pdf_import(gen_random_uuid(),'sixth.pdf',100,repeat('a',64))$$,'PT429',null,'Active cap enforced');
select ok(discard_pdf_import('27000000-0000-4000-8000-000000000006'),'Owner discards upload');
select is(discard_pdf_import('27000000-0000-4000-8000-000000000006'),false,'Discard missing idempotent');
reset role;
select lives_ok($$delete from auth.users where id='17000000-0000-4000-8000-000000000001'$$,'Account cleanup cascades');
select is((select count(*) from pdf_imports where user_id='17000000-0000-4000-8000-000000000001'),0::bigint,'Imports removed with account');
select * from finish();
rollback;
